def num_islands(grid: list[list[str]]) -> int:
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    count = 0
    for i in range(rows):
        for j in range(cols):
            if g[i][j] == '1':
                count += 1
                stack = [(i, j)]
                g[i][j] = '0'
                while stack:
                    r, c = stack.pop()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and g[nr][nc] == '1':
                            g[nr][nc] = '0'
                            stack.append((nr, nc))
    return count
