def json_escape(s: str) -> str:
    special = {
        '"': '\\"',
        '\\': '\\\\',
        '\n': '\\n',
        '\t': '\\t',
        '\r': '\\r',
        '\b': '\\b',
        '\f': '\\f',
    }
    parts = ['"']
    for ch in s:
        if ch in special:
            parts.append(special[ch])
        elif ord(ch) < 0x20:
            parts.append('\\u%04x' % ord(ch))
        else:
            parts.append(ch)
    parts.append('"')
    return ''.join(parts)
